def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/environment/input/constitution_beach_datasheet.csv'
    df = pd.read_csv(path)
    return pd.concat([df.head(5), df.tail(5)])

def process(discordant_days_2024):
    import pandas as pd
    df = discordant_days_2024.copy()
    # discordant column may be boolean or string; normalize
    df['discordant_flag'] = df['discordant'].astype(str).str.lower().isin(['true','1','t','yes']) if df['discordant'].dtype != bool else df['discordant']
    out = pd.DataFrame({
        'discordant_days_2024': [int(df['discordant_flag'].sum())],
        'total_sample_days_2024': [df.shape[0]]
    })
    return out
